export const versionMap = {
  Toyota: { E: "standard", G: "other", V: "premium", Q: "premium" },
  Honda: { G: "standard", L: "other", RS: "premium" },
  Hyundai: { Base: "standard", MT: "standard", AT: "other", Special: "other", Premium: "premium" },
  Kia: { Standard: "standard", Deluxe: "other", Luxury: "other", Premium: "premium", Signature: "premium" },
  Mazda: { Standard: "standard", Deluxe: "other", Luxury: "other", Premium: "premium", Signature: "premium" },
  "Mercedes-Benz": { C180: "standard", C200: "other", C300: "premium", E180: "standard", E200: "other", E300: "premium", S450: "premium" },
  BMW: { "320i": "standard", "330i": "premium", "520i": "standard", "530i": "premium", "730i": "standard", "740i": "premium" },
  Ford: { Base: "standard", XLS: "standard", XLT: "other", Titanium: "premium", Wildtrak: "premium", Sport: "premium" },
  Mitsubishi: { MT: "standard", AT: "other", CVT: "other", Premium: "premium" },
  Nissan: { MT: "standard", AT: "other", CVT: "other", VL: "premium" },
  Suzuki: { MT: "standard", AT: "other", GL: "standard", GLX: "premium" },
  VinFast: { Base: "standard", Plus: "premium", Premium: "premium" },
  Chevrolet: { LS: "standard", LT: "other", LTZ: "premium" },
  MG: { STD: "standard", COM: "other", LUX: "premium" },
  Peugeot: { Active: "standard", Allure: "other", GT: "premium" }
};

export const classifyByBrand = (brand, version) => {
  if (!brand || !version) return "other";

  const map = versionMap[brand];
  if (!map) return "other";

  // Chuẩn hóa chuỗi nhập vào để tránh lỗi khoảng trắng hoặc in hoa in thường
  const v = version.toString().trim().toUpperCase();

  // Tìm kiếm sự tồn tại của từ khoá phiên bản trong chuỗi version
  // Ưu tiên trùng khớp chính xác (exact match) trước
  for (const key in map) {
    if (v === key.toUpperCase()) {
      return map[key];
    }
  }

  // Nếu không có trùng khớp chính xác, tìm kiếm gần đúng (contains)
  for (const key in map) {
    if (v.includes(key.toUpperCase())) {
      return map[key];
    }
  }

  return "other";
};

export const getVersionFactor = (type) => {
  switch (type) {
    case "standard": return 0.9;
    case "other": return 1.0;
    case "premium": return 1.15;
    default: return 1.0;
  }
};

export const calculateValuation = (formData) => {
  const currentYear = new Date().getFullYear();
  const year = parseInt(formData.year) || currentYear;
  let odo = parseInt(formData.odo) || 0;

  // 1. price_new based on brand (using average of min-max)
  let price_new = 1000000000; // default 1B
  switch (formData.brand) {
    case 'Toyota': price_new = (450000000 + 1300000000) / 2; break;
    case 'Honda': price_new = (500000000 + 1300000000) / 2; break;
    case 'Kia': price_new = (350000000 + 1100000000) / 2; break;
    case 'Hyundai': price_new = (350000000 + 800000000) / 2; break;
    case 'Mazda': price_new = (650000000 + 1000000000) / 2; break;
    case 'VinFast': price_new = (300000000 + 1300000000) / 2; break;
    case 'Ford': price_new = (650000000 + 1500000000) / 2; break;
    // other brands fallback to 1B
  }

  // 2. years_used
  const years_used = Math.max(0, currentYear - year);

  // 3. depreciation_rate
  let depreciation_rate = 0.5;
  if (years_used < 1) depreciation_rate = 0.9;
  else if (years_used <= 3) depreciation_rate = 0.7; // 1-3
  else if (years_used <= 6) depreciation_rate = 0.5; // 3-6
  else if (years_used < 10) depreciation_rate = 0.3; // 6-10
  else depreciation_rate = 0.2; // >= 10

  // 4. base_price
  const base_price = price_new * depreciation_rate;

  // 5. total_factor
  let brand_factor = 1.0;
  if (['Toyota', 'Honda'].includes(formData.brand)) brand_factor = 1.05;
  else if (formData.brand === 'Kia') brand_factor = 0.95;

  // Default values for missing fields from form
  const origin_factor = 1.0; 
  const color_factor = 1.0;
  const condition_factor = 1.0;

  const versionType = classifyByBrand(formData.brand, formData.version);
  const version_factor = getVersionFactor(versionType);

  const total_factor = brand_factor * origin_factor * color_factor * condition_factor * version_factor;

  // 6. km_depreciation
  const km_depreciation = (odo / 10000) * 0.02 * price_new;

  // 7. final_price
  let final_price = (base_price * total_factor) - km_depreciation;
  if (final_price < 0) final_price = 0;

  // Simulate market price range (roughly 85% to 95% of Store Car Price depending on factors)
  // Our estimated final_price is what the Store Car buys it for.
  // The system shows "Store Car Price" and "Market Price".
  const storeCarPriceMax = final_price;
  const storeCarPriceMin = final_price * 0.98;

  const marketPriceMax = final_price * 0.95;
  const marketPriceMin = final_price * 0.85;

  return {
    estimated_price: final_price,
    price_new,
    years_used,
    breakdown: {
      base_price,
      depreciation_rate,
      total_factor,
      km_depreciation,
      versionType,
      version_factor
    },
    uiData: {
      storeCarPrice: `${Math.round(storeCarPriceMin / 1000000)} triệu - ${Math.round(storeCarPriceMax / 1000000)} triệu`,
      marketPrice: `${Math.round(marketPriceMin / 1000000)} triệu - ${Math.round(marketPriceMax / 1000000)} triệu`,
      increasePercentage: '+4%' // Assuming we offer 4% more than market
    }
  };
};
